The following Terraform configuration deploys an AWS Lightsail PostgreSQL managed database and configures it to create a final snapshot when the database is deleted. It includes:

- AWS provider configuration in `us-east-1`
- A Lightsail PostgreSQL database
- A generated secure master password
- Final snapshot creation enabled via `skip_final_snapshot = false`
- A unique final snapshot name using a random suffix

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the Lightsail PostgreSQL database will be created."
  type        = string
  default     = "us-east-1"
}

variable "availability_zone" {
  description = "Availability Zone for the Lightsail database."
  type        = string
  default     = "us-east-1a"
}

variable "database_name" {
  description = "Name of the Lightsail relational database resource."
  type        = string
  default     = "lightsail-postgres-db"
